import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` — the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (§12b) — the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited → renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) — an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` — this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <HeroSkeleton className="h-4 w-64 max-w-full rounded" />
    }
    // no seat cap at this phase → no honest scarcity reason → stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` — the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ⇒ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `·` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // §5a: icon matches the FONT-SIZE of the text beside it — `sm`
                        // (14px) ⇒ `size-3.5`. §5.0a: below `size-5` ⇒ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) — but they're still TWO SEPARATE cluster items, since the
                    // `·` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}₫ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` — single-component namespace ⇒ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

import React from "react"
import { BuildingsIcon, LockIcon } from "@phosphor-icons/react"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Typography, type TypographyIcon } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ConsultantProfileBody` — the full detail content of one consultant's profile:
 * photo, name+role, a pressable company row, the full bio, and either real
 * contact links once unlocked or a locked callout with a way to unlock them.
 * The detail sibling of `ConsultantCard`. `contactUnlocked` only changes which
 * content fills the last slot, not the outer frame.
 */

/** One way to reach this consultant once contact is unlocked — plain navigable data. */
export interface ConsultantProfileBodyContactLink {
    /** Stable React key. */
    key: string
    /** Display label, e.g. "hoa.nguyen@techcorp.vn" or "090 123 4567". */
    label: string
    /** Where the link goes — `mailto:`/`tel:`/`https:` etc. The atom renders it, never fetches it. */
    href: string
    /** Optional leading glyph (mail/phone/chat) as a COMPONENT, not JSX. */
    icon?: TypographyIcon
}

/** One consultant's full profile — plain data, the block builds the detail view from it. */
export interface ConsultantProfileBodyConsultant {
    /** Full name — the profile's accessible heading. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. The company row disappears when absent. */
    companyTitle?: string
    /** Full bio — rendered in full here, unlike `ConsultantCard`'s clamped teaser. */
    description?: string
    /** Photo URL. Empty/missing → `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
    /** `true` → real `contactLinks` are shown. `false` → the locked callout is shown instead. */
    contactUnlocked: boolean
    /** Ways to reach this consultant. Only read when `contactUnlocked` is `true`. */
    contactLinks?: Array<ConsultantProfileBodyContactLink>
}

/** Props for {@link ConsultantProfileBody}. */
export interface ConsultantProfileBodyProps {
    /** The consultant whose profile this fills. */
    consultant: ConsultantProfileBodyConsultant
    /** Fired when the visitor presses the company row. Row is disabled without it. */
    onOpenCompany?: () => void
    /** Fired from the locked callout's CTA. No CTA renders without it. */
    onImproveCv?: () => void
    /**
     * `true` → `Image` and every `Typography` line switch to their own shimmer, the
     * company button is disabled, and the contact fork shows a neutral shimmer
     * instead of picking a branch (see file header). There is no id to open yet.
     */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-contact callout — block-owned wording (§14d.1), see file header. */
const LOCKED_TITLE = "Contact is locked"
const LOCKED_DESCRIPTION = "Improve your CV to unlock this consultant's contact information."
const LOCKED_CTA_LABEL = "Improve CV"

/**
 * The full profile-detail content for one consultant. See the file header for
 * the full contract, the fork between `ConsultantCard`'s tile shape and this
 * one, and the judgment calls behind the contact fork.
 *
 * @param props - {@link ConsultantProfileBodyProps}
 */
const ConsultantProfileBody = ({
    consultant,
    onOpenCompany,
    onImproveCv,
    isSkeleton = false,
}: ConsultantProfileBodyProps) => {
    const { fullName, jobTitle, companyTitle, description, avatarUrl, contactUnlocked, contactLinks } = consultant

    const nameRow = (
        <StackV gap={1} align="center" principle="name-handle"
            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
            isSkeleton={isSkeleton} items={[
                () => (
                    <Typography
                        size="h4"
                        weight="bold"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={fullName}

                    />
                ),
                ...(isSkeleton || jobTitle ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={jobTitle}

                    />
                )] : []),
            ]} />
    )

    // identity: centered photo, name+role, pressable company row
    const identity = (
        <StackV gap={4} align="center" principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            isSkeleton={isSkeleton} items={[
                () => (
                    <div className="w-28">
                        <Image
                            src={avatarUrl}
                            alt={fullName}
                            ratio="square"
                            radius="full"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                () => nameRow,
                ...(isSkeleton || companyTitle ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="sm"
                        label={companyTitle ?? ""}
                        prefixIcon={BuildingsIcon}
                        onPress={onOpenCompany}
                        isDisabled={isSkeleton || !onOpenCompany}

                    />
                )] : []),
            ]} />
    )

    // contact fork — see file header for why loading shimmers neutrally
    const contactFork = isSkeleton ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={[
            () => <Typography size="sm" isSkeleton />,
            () => <Typography size="sm" isSkeleton />,
        ]} />
    ) : contactUnlocked ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={(contactLinks ?? []).map((link) => () => (
            <Typography
                size="sm"
                isLink
                href={link.href}
                prefixIcon={link.icon}
                text={link.label}

            />
        ))} />
    ) : (
        <Callout
            status="warning"
            icon={LockIcon}
            title={LOCKED_TITLE}
            description={LOCKED_DESCRIPTION}
            actionLabel={onImproveCv ? LOCKED_CTA_LABEL : undefined}
            onAction={onImproveCv}


        />
    )

    return (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "ConsultantProfileBody" }}
            items={[
                () => identity,
                // full bio — no clamp, unlike ConsultantCard's directory teaser
                ...(isSkeleton || description ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}

                    />
                )] : []),
                () => contactFork,
            ]}
        />
    )
}

export { ConsultantProfileBody }

"use client"

import React, { useEffect, useMemo, useState } from "react"
import { AnimatePresence, motion } from "framer-motion"

const CONFETTI_PIECE_COUNT = 24
const CONFETTI_DURATION_MS = 2400
const CONFETTI_COLOR_CLASS = ["bg-accent", "bg-success", "bg-warning", "bg-danger"]

/** One falling piece's randomized flight. */
interface ConfettiPiece {
    key: number
    leftPercent: number
    delaySeconds: number
    durationSeconds: number
    rotateDegrees: number
    colorClass: string
}

/** Props for the internal {@link Confetti} effect. */
interface ConfettiProps {
    /** Bumping this replays the burst. */
    celebrateKey: number
}

/**
 * Fires a burst of falling particles every time `celebrateKey` changes (including
 * on first mount, since a fresh board can already open on a celebrated placement).
 * Self-clears after the flight so it never lingers as dead, invisible DOM.
 */
export const Confetti = ({ celebrateKey }: ConfettiProps) => {
    const [isPlaying, setIsPlaying] = useState(false)

    useEffect(() => {
        setIsPlaying(true)
        const timer = window.setTimeout(() => setIsPlaying(false), CONFETTI_DURATION_MS)
        return () => window.clearTimeout(timer)
    }, [celebrateKey])

    const pieces = useMemo<Array<ConfettiPiece>>(
        () =>
            Array.from({ length: CONFETTI_PIECE_COUNT }, (_, index) => ({
                key: index,
                leftPercent: Math.random() * 100,
                delaySeconds: Math.random() * 0.4,
                durationSeconds: 1.6 + Math.random() * 0.8,
                rotateDegrees: Math.random() * 360,
                colorClass: CONFETTI_COLOR_CLASS[index % CONFETTI_COLOR_CLASS.length],
            })),
        [celebrateKey],
    )

    if (!isPlaying) {
        return null
    }

    return (
        <div aria-hidden className="pointer-events-none fixed inset-0 z-50 overflow-hidden">
            <AnimatePresence>
                {pieces.map((piece) => (
                    <motion.span
                        key={piece.key}
                        className={`absolute top-[-5%] size-2 rounded-sm ${piece.colorClass}`}
                        style={{ left: `${piece.leftPercent}%` }}
                        initial={{ y: "-10vh", opacity: 1, rotate: 0 }}
                        animate={{ y: "110vh", opacity: [1, 1, 0], rotate: piece.rotateDegrees }}
                        transition={{ duration: piece.durationSeconds, delay: piece.delaySeconds, ease: "easeIn" }}
                    />
                ))}
            </AnimatePresence>
        </div>
    )
}

import React from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"

/** Props for the local {@link CommandSkeleton} mirror. */
interface CommandSkeletonProps {
    /** How many placeholder code lines to draw. Defaults to 1. */
    lines?: number
}

/**
 * Placeholder mirror of the code-block chrome `MarkdownContent`'s `pre` renderer
 * draws (border, header divider, lang label) — see file header for why this
 * block owns it instead of `MarkdownContent` shipping an `isSkeleton`.
 */
export const CommandSkeleton = ({ lines = 1 }: CommandSkeletonProps) => (
    <div className="overflow-hidden rounded-2xl border border-default bg-default/30">
        <StackH
            gap={1}
            align="center"
            justify="between"
            padding={{ x: 4, y: 3 }}
            principle="control-pad"
            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
            body={() => <Typography size="xs" isSkeleton />}
        />
        <Divider />
        <StackV
            gap={1}
            padding={4}
            principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            items={[() => (
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={Array.from({ length: lines }, () => () => (
                        <Typography size="xs" isSkeleton />
                    ))}
                />
            )]}
        />
    </div>
)

import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/**
 * BLOCK — `QaChatBubble`: the one surface every message in a Q&A
 * conversation renders inside — accent+right for the viewer's own message,
 * neutral+left for anyone else's. `rounded-2xl`, the documented chat
 * exception to the usual card `rounded-3xl`.
 */

/** Props for {@link QaChatBubble}. */
export interface QaChatBubbleProps {
    /** `"user"` → the viewer's own message (accent, tail on the right). `"assistant"` → anyone else's (neutral, tail on the left). */
    role: "user" | "assistant"
    /** Bubble content — typically a compact {@link import("@sb-components/composites/viewers/MarkdownContent/MarkdownContent").MarkdownContent}. */
    children: ReactNode
    /** `true` → the bubble draws a shimmer block instead of `children`. */
    isSkeleton?: boolean
}

/**
 * The one message-bubble surface a `QaQuestionThread` conversation renders,
 * tinted and tailed toward the viewer's own side or the other party's.
 *
 * @param props - {@link QaChatBubbleProps}
 */
const QaChatBubble = ({ role, children, isSkeleton = false }: QaChatBubbleProps) => (
    <div

        className={cn(
            "min-w-0 rounded-2xl px-3 py-3",
            role === "user"
                ? "rounded-tr-md bg-accent-soft text-accent-soft-foreground"
                : "rounded-tl-md bg-default text-foreground",
            isSkeleton && "h-10 w-40 animate-pulse",
        )}
    >
        {!isSkeleton ? children : null}
    </div>
)

export { QaChatBubble }

import React from "react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { DrawerShell } from "@sb-components/composites/layout/DrawerShell/DrawerShell"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { EvaluateActionRow } from "./EvaluateActionRow"
import { GithubGradingSettingsBody } from "./GithubGradingSettingsBody"
import { GithubUrlField } from "./GithubUrlField"
import { SettingsSummaryRow } from "./SettingsSummaryRow"
import { TaskResultSummary } from "./TaskResultSummary"
import { type TaskSubmissionPanelProps } from "./types"

export type {
    TaskSubmissionAutosaveStatus,
    TaskSubmissionSettingsSummary,
    TaskSubmissionResult,
    GithubGradingSettingsFormProps,
    TaskSubmissionPanelProps,
} from "./types"

/**
 * `TaskSubmissionPanel` — the project-level (not per-task) sticky console for a
 * GitHub-graded personal project: repo URL, an evaluate action + AI status, the
 * latest result summary, and a settings drawer for language/branch/token. Sibling of
 * `ChallengeDeliverableList` (one repo URL for the whole project vs. one row per
 * requirement; the settings drawer's content is in scope here). Autosave wording,
 * the AI status line, and the evaluate button's busy state are states of `Default`;
 * losing the `TaskResultSummary` subtree (no `latestResult`) and opening the settings
 * drawer each get their own leaf.
 */

/**
 * The project-level submission console. See the file header for the full
 * reuse ledger and the judgement calls (trimmed result summary, shared
 * status-line vocabulary, baked-in sticky position).
 *
 * @param props - {@link TaskSubmissionPanelProps}
 */
const TaskSubmissionPanel = ({
    githubUrl,
    onGithubUrlChange,
    urlError,
    autosaveStatus,
    settingsSummary,
    isSettingsOpen,
    onSettingsOpenChange,
    onEvaluate,
    isEvaluating = false,
    aiStatusText,
    latestResult,
    settingsFormProps,
    isSkeleton = false,
}: TaskSubmissionPanelProps) => (
    <div className="sticky top-4 z-10">
        <SurfaceCard
            label="Submit project"
            isSkeleton={isSkeleton}

            body={() => (
                <StackV
                    gap={4}
                    isSkeleton={isSkeleton}

                    items={[
                        () => (
                            <GithubUrlField
                                githubUrl={githubUrl}
                                onGithubUrlChange={onGithubUrlChange}
                                urlError={urlError}
                                autosaveStatus={autosaveStatus}
                                isSkeleton={isSkeleton}

                            />
                        ),
                        () => (
                            <SettingsSummaryRow
                                settingsSummary={settingsSummary}
                                onOpenSettings={() => onSettingsOpenChange(true)}
                                isSkeleton={isSkeleton}

                            />
                        ),
                        () => (
                            <EvaluateActionRow
                                onEvaluate={onEvaluate}
                                isEvaluating={isEvaluating}
                                aiStatusText={aiStatusText}
                                isSkeleton={isSkeleton}

                            />
                        ),
                        () => <TaskResultSummary result={latestResult} isSkeleton={isSkeleton} />,
                    ]}
                />
            )}
        />

        <DrawerShell
            isOpen={isSettingsOpen}
            onOpenChange={onSettingsOpenChange}
            title="Grading settings"
            description="The language, branch and token StarCi uses to read and grade your repo."
            footer={() => (
                <Button
                    label="Save"
                    variant="primary"
                    onPress={settingsFormProps.onSave}
                    isPending={settingsFormProps.isSaving}

                />
            )}

            body={() => <GithubGradingSettingsBody form={settingsFormProps} />}
        />
    </div>
)

export { TaskSubmissionPanel }

import React from "react"
import { QuotaBar } from "@/components/blocks/ai/QuotaBar"
import { StackV } from "@/components/frames/Stack"

/**
 * `AiQuotaLane` — one lane's pair of rolling-window quota bars ("next 5 hours"
 * above "this week"), shared by the Auto tab and the Premium branch of the
 * Subscription tab inside `AiQuotaModal`. Both rows are the same `QuotaBar`
 * composition reading a different window. Unset `data`/`isLoading` shimmers
 * both bars.
 */

/** One rolling-window quota reading, ready to draw as a single {@link ProgressBar}. */
export interface AiQuotaWindow {
    /** Amount consumed in this window. */
    used: number
    /** Cap for this window (`0` reads as "no allowance"). */
    limit: number
    /** Reset line under the bar (e.g. `"Resets at 18:50 on 06/01"`). `null`/unset → no line. */
    resetLabel?: string | null
}

/** The two rolling windows one {@link AiQuotaLane} tracks. */
export interface AiQuotaLaneData {
    /** Next-5-hours rolling window. */
    window5h: AiQuotaWindow
    /** This-week rolling window. */
    windowWeek: AiQuotaWindow
}

/** Props for {@link AiQuotaLane}. */
export interface AiQuotaLaneProps {
    /** The lane's two windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` → this lane's own fetch is in flight; both bars draw their skeleton mirror. */
    isLoading: boolean
}

/**
 * The lane's two bars. See the file header for what it owns (window labels)
 * and what it deliberately does not (fetching — `data` is a plain prop, never
 * an internal SWR call — and the fill-tone ramp, which `QuotaBar` owns).
 *
 * @param props - {@link AiQuotaLaneProps}
 */
const AiQuotaLane = ({ data, isLoading }: AiQuotaLaneProps) => {
    const showSkeleton = isLoading || !data

    return (
        <StackV
            identity={{ tier: "block", component: "AiQuotaLane" }}
            gap={4}
            items={[
                () => (
                    <QuotaBar
                        label="Next 5 hours"
                        used={data?.window5h.used ?? 0}
                        limit={data?.window5h.limit ?? 0}
                        resetLabel={data?.window5h.resetLabel}
                        isSkeleton={showSkeleton}
                    />
                ),
                () => (
                    <QuotaBar
                        label="This week"
                        used={data?.windowWeek.used ?? 0}
                        limit={data?.windowWeek.limit ?? 0}
                        resetLabel={data?.windowWeek.resetLabel}
                        isSkeleton={showSkeleton}
                    />
                ),
            ]}
        />
    )
}

export { AiQuotaLane }

import type { IconComponent } from "@/types"
import { CheckCircleIcon, XCircleIcon, HourglassIcon } from "@phosphor-icons/react"
import { AiBalancerKeyStatus } from "@/modules/api/graphql/queries/enums/ai-balancer-key-status"

/** Visual token for one balancer key status badge. */
export interface AiBalancerKeyStatusVisual {
    /** Tailwind classes for the status chip. */
    chipClassName: string
    /** Icon component reference. */
    Icon: IconComponent
}

/**
 * Status chip styles for dark admin surfaces.
 */
export const AI_BALANCER_KEY_STATUS_DARK_MAP: Record<string, AiBalancerKeyStatusVisual> = {
    [AiBalancerKeyStatus.Active]: {
        chipClassName: "bg-emerald-500/15 text-emerald-300 border-emerald-500/30",
        Icon: CheckCircleIcon,
    },
    [AiBalancerKeyStatus.Disabled]: {
        chipClassName: "bg-rose-500/15 text-rose-300 border-rose-500/30",
        Icon: XCircleIcon,
    },
    [AiBalancerKeyStatus.Probing]: {
        chipClassName: "bg-amber-500/15 text-amber-300 border-amber-500/30",
        Icon: HourglassIcon,
    },
}

/**
 * Status chip styles for light learn surfaces (StarCi AI page).
 */
export const AI_BALANCER_KEY_STATUS_LIGHT_MAP: Record<string, AiBalancerKeyStatusVisual> = {
    [AiBalancerKeyStatus.Active]: {
        chipClassName: "bg-emerald-100 text-emerald-800 border-emerald-200",
        Icon: CheckCircleIcon,
    },
    [AiBalancerKeyStatus.Disabled]: {
        chipClassName: "bg-rose-100 text-rose-800 border-rose-200",
        Icon: XCircleIcon,
    },
    [AiBalancerKeyStatus.Probing]: {
        chipClassName: "bg-amber-100 text-amber-800 border-amber-200",
        Icon: HourglassIcon,
    },
}

import { useReactFlow } from "@xyflow/react"
import { useEffect } from "react"
import { useAppSelector } from "@/redux/hooks"

/** Default zoom when landing on the "you are here" module — readable, not the tiny fit-all. */
const CURRENT_MODULE_ZOOM = 1.2

/**
 * Sets the mind-map's initial camera. When the viewer's current ("you are here")
 * module is known, it lands centred on it at a readable zoom — orientation first,
 * not the tiny fit-everything view. Otherwise (guest / no progress) it eases into a
 * fit of the whole graph.
 *
 * @param currentModuleId - The module that owns the viewer's next content task, if any.
 */
export const useMindMapFitView = (currentModuleId?: string) => {
    /** The course entity. */
    const entity = useAppSelector((state) => state.course.entity)
    /** React Flow camera helpers. */
    const { fitView, setCenter, getNode } = useReactFlow()
    /** The useEffect to set the initial mind map view. */
    useEffect(() => {
        /** If the entity is not found, return. */
        if (!entity) {
            return
        }
        /** The request animation frame to set the initial view once nodes are laid out. */
        const id = requestAnimationFrame(() => {
            const node = currentModuleId ? getNode(currentModuleId) : undefined
            if (node) {
                // land centred on the current module so the learner sees "where am I" up close
                const width = node.measured?.width ?? 300
                const height = node.measured?.height ?? 100
                void setCenter(
                    node.position.x + width / 2,
                    node.position.y + height / 2,
                    { zoom: CURRENT_MODULE_ZOOM, duration: 500 },
                )
                return
            }
            // no current module (guest / all done) → ease into the whole-graph overview
            void fitView({ padding: 0.2, duration: 500 })
        })
        /** The cleanup function to cancel the request animation frame. */
        return () => cancelAnimationFrame(id)
    }, [entity, entity?.id, entity?.modules?.length, currentModuleId, fitView, setCenter, getNode])
}

import React from "react"
import { BookOpenIcon, CodeIcon, FlaskIcon, PlayIcon, PuzzlePieceIcon } from "@phosphor-icons/react"
import { Toolbar, type ToolbarTabItem } from "@/components/composites/navigation/Toolbar"

/**
 * `ContentModeNav` — how to view this lesson: modes on the left, code language
 * on the right. Switching mode changes the route, so this is navigation, not a
 * tab/panel pair. A locked mode renders muted but still fires `onModeChange` —
 * the screen decides a locked tap opens the paywall. The mode group carries the
 * one accent; the language group is neutral. No `isSkeleton` — it is static
 * chrome. The right group appearing is its own leaf; selected mode and lock
 * state are data.
 */

/** The ways a lesson can be looked at. */
export type ContentMode = "content" | "sandbox" | "challenges" | "aiLab"

/**
 * Label + icon per mode. The BLOCK owns this table: it is the vocabulary of the
 * reading experience, and a caller that could pass it would own the wording.
 */
const MODE_LABEL: Record<ContentMode, string> = {
    content: "Content",
    sandbox: "Sandbox",
    challenges: "Challenges",
    aiLab: "AI Lab",
}

// `size-5` — the tab's own text is `text-sm` (HeroUI `Tabs.Tab` default, `tabs.css`
// `.apply ... text-sm`), and this icon sits INSIDE that control, so it matches the
// control's own box height (line-height 20px), not the bare glyph size (§5a icon=DIV
// case) — `size-3.5` would be the icon=TEXT pairing, wrong for an icon inside a tab.
const MODE_ICON: Record<ContentMode, React.ReactNode> = {
    content: <BookOpenIcon aria-hidden focusable="false" className="size-5" />,
    sandbox: <PlayIcon aria-hidden focusable="false" className="size-5" />,
    challenges: <PuzzlePieceIcon aria-hidden focusable="false" className="size-5" />,
    aiLab: <FlaskIcon aria-hidden focusable="false" className="size-5" />,
}

// Same icon on every language tab (doesn't distinguish TS from Go) — the trigger
// affordance for "this collapses to a language switcher" below `@app-sm`, not a
// per-language mark. Matches `Toolbar`'s own collapsed-group story convention
// (`RightNeutralCollapsed`, every item sharing one `GlobeIcon`) — the collapsed
// `Select` trigger is ICON-ONLY (§13c), so a language row with no icon of its own
// would render a blank trigger once `collapseRightOnMobile` is on.
const LANGUAGE_ICON = <CodeIcon aria-hidden focusable="false" className="size-4" weight="bold" />

/** One offered mode — whether it is locked. */
export interface ContentModeOption {
    /** Which mode this entry is. */
    mode: ContentMode
    /** `true` → premium and not yet bought: rendered muted, still clickable. */
    isLocked?: boolean
}

/** One entry in the fixed code-language catalog. */
export interface ContentLanguage {
    /** Stable id used as the selection key, e.g. `"typescript"`. */
    key: string
    /** Display label, already localized by the caller. */
    label: string
    /** `true` → this lesson has no body in this language: rendered disabled, not omitted. */
    isDisabled?: boolean
}

/** Props for {@link ContentModeNav}. */
export interface ContentModeNavProps {
    /** Modes this lesson offers, in display order. */
    modes: Array<ContentModeOption>
    /** Which mode is being looked at now. */
    mode: ContentMode
    /**
     * Fired with the mode the reader picked — INCLUDING a locked one. The screen
     * decides what a locked pick means (typically: open the paywall instead of
     * navigating). The block never swallows the event.
     */
    onModeChange: (mode: ContentMode) => void
    /**
     * The FULL fixed language catalog (TypeScript/Java/C#/Go, in that order),
     * each carrying its own `isDisabled` — a lesson missing a language still
     * lists it, dimmed, rather than shrinking the row (real `src` never hides
     * a language, only greys it out). Fewer than two AVAILABLE (non-disabled)
     * entries → the right group is not drawn at all: a switcher with one live
     * option is a control that cannot do anything.
     */
    languages?: Array<ContentLanguage>
    /** Which language is being read. */
    language?: string
    /** Fired with the language the reader picked. */
    onLanguageChange?: (language: string) => void
    /**
     * Accessible name for the mode row, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears loose tabs.
     */
    ariaLabel: string
    /** Accessible name for the language group. Required whenever `languages` is set. */
    languageAriaLabel?: string
}

/**
 * The lesson's mode row. See the file header for why locked modes stay clickable
 * and why this is navigation rather than a tab/panel pair.
 *
 * @param props - {@link ContentModeNavProps}
 */
const ContentModeNav = ({
    modes,
    mode,
    onModeChange,
    languages,
    language,
    onLanguageChange,
    ariaLabel,
    languageAriaLabel,
}: ContentModeNavProps) => {
    const items: Array<ToolbarTabItem> = modes.map((entry) => ({
        key: entry.mode,
        label: MODE_LABEL[entry.mode],
        icon: MODE_ICON[entry.mode],
        // MUTED, not disabled: a locked mode must still receive the click so the
        // screen can open the offer. Disabling it kills the very thing this row is for.
        muted: entry.isLocked,
    }))

    // A switcher with one AVAILABLE option is a control that cannot do anything — count
    // only the non-disabled entries, since the catalog itself always lists all four.
    const availableLanguageCount = (languages ?? []).filter((entry) => !entry.isDisabled).length
    const hasLanguages = availableLanguageCount > 1 && language != null && onLanguageChange != null

    return (
        <Toolbar
            leftTabs={{
                items,
                selectedKey: mode,
                ariaLabel,
                onSelectionChange: (key) => onModeChange(String(key) as ContentMode),
            }}
            rightTabs={
                hasLanguages
                    ? {
                        items: (languages ?? []).map((entry) => ({
                            key: entry.key,
                            label: entry.label,
                            icon: LANGUAGE_ICON,
                            isDisabled: entry.isDisabled,
                        })),
                        selectedKey: language as string,
                        ariaLabel: languageAriaLabel ?? "",
                        onSelectionChange: (key) => onLanguageChange?.(String(key)),
                    }
                    : undefined
            }
            // The language group is a "same lesson, different presentation" toggle, so
            // it stays NEUTRAL: only the mode group carries accent, and the row keeps
            // ONE accent signal rather than two competing for the eye.
            rightTabsNeutral
            // A set-once preference, not a second navigation choice — folds behind a
            // compact icon-only dropdown below `@app-sm` instead of crowding the reading
            // column with 4 inline tabs.
            collapseRightOnMobile
        />
    )
}

export { ContentModeNav }

