"use client"

import {
    useCallback,
    useEffect,
    useState,
} from "react"

/** A single entry in the "on this page" outline. */
export interface TocHeading {
    /** Anchor id of the heading element (matches the rendered `id`). */
    id: string
    /** Plain-text label shown in the outline. */
    text: string
    /** Heading depth (2 or 3) used to indent the row. */
    level: number
}

/** Result of {@link useTableOfContents}. */
export interface UseTableOfContentsResult {
    /** The ordered headings discovered in the active lesson body. */
    headings: Array<TocHeading>
    /** Id of the heading currently in view (scroll-spy), or undefined. */
    activeId?: string
    /** Smooth-scroll the article to the given heading id and mark it active. */
    onJump: (id: string) => void
}

/** Id of the lesson article container the outline scans within. */
const ARTICLE_ID = "lesson-article"

/**
 * Builds the "on this page" outline for the active lesson by scanning the rendered
 * article (`#lesson-article [data-toc]`) for heading anchors, then tracks which
 * heading is in view (scroll-spy) and exposes a smooth-scroll jump.
 *
 * DOM-driven (not data-driven) so it works for any rendered body — markdown
 * headings are tagged with `id` + `data-toc` by the shared `MarkdownContent`
 * renderer. Re-scans whenever `rescanKey` changes (lesson navigation / language
 * switch) and while the article subtree mutates (async markdown render).
 *
 * @param rescanKey - A value that changes when the active lesson changes (its id),
 *   forcing a re-scan. Pass `undefined` when no lesson is active.
 * @returns {@link UseTableOfContentsResult} headings, the active id, and a jumper.
 */
export const useTableOfContents = (rescanKey: string | undefined): UseTableOfContentsResult => {
    const [headings, setHeadings] = useState<Array<TocHeading>>([])
    const [activeId, setActiveId] = useState<string | undefined>(undefined)

    // scan the rendered article for heading anchors; re-run on lesson change +
    // while the article subtree mutates (markdown renders client-side, async).
    useEffect(() => {
        let frame = 0

        const scan = () => {
            const container = document.getElementById(ARTICLE_ID)
            if (!container) {
                setHeadings([])
                return
            }
            const nodes = Array.from(container.querySelectorAll<HTMLElement>("[data-toc]"))
            const next = nodes
                .filter((node) => node.id)
                .map((node) => ({
                    id: node.id,
                    // prefer the clean data-toc-label (set by MarkdownContent) so the hover
                    // anchor "#" / inline code in the heading never leaks into the outline.
                    text: node.dataset.tocLabel ?? node.textContent?.trim() ?? "",
                    level: Number(node.dataset.tocLevel ?? "2"),
                }))
            setHeadings(next)
        }

        // coalesce mutation bursts into a single scan per frame.
        const schedule = () => {
            if (frame) {
                return
            }
            frame = requestAnimationFrame(() => {
                frame = 0
                scan()
            })
        }

        // Observe a STABLE root (document.body) instead of polling a fixed number
        // of frames for #lesson-article. On a hard reload the article mounts only
        // after the SWR fetch + markdown render resolves, which can exceed any
        // fixed timeout — the old 60-frame poll then gave up with an empty outline
        // and never re-scanned. body always exists, so we reliably catch both the
        // article mounting and its async heading render, on hard reload AND SPA nav.
        scan()
        const observer = new MutationObserver(schedule)
        observer.observe(document.body, { childList: true, subtree: true })

        return () => {
            if (frame) {
                cancelAnimationFrame(frame)
            }
            observer.disconnect()
        }
    }, [rescanKey])

    // scroll-spy: mark the top-most heading currently in the viewport band.
    useEffect(() => {
        if (headings.length === 0) {
            setActiveId(undefined)
            return
        }
        const elements = headings
            .map((heading) => document.getElementById(heading.id))
            .filter((element): element is HTMLElement => Boolean(element))
        if (elements.length === 0) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                const visible = entries
                    .filter((entry) => entry.isIntersecting)
                    .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)
                if (visible[0]?.target.id) {
                    setActiveId(visible[0].target.id)
                }
            },
            {
                // bias the active band just under the sticky navbar
                rootMargin: "-72px 0px -70% 0px",
                threshold: 0,
            },
        )
        elements.forEach((element) => observer.observe(element))
        return () => observer.disconnect()
    }, [headings])

    const onJump = useCallback((id: string) => {
        const element = document.getElementById(id)
        if (element) {
            element.scrollIntoView({ behavior: "smooth", block: "start" })
            setActiveId(id)
        }
    }, [])

    return {
        headings,
        activeId,
        onJump,
    }
}

import React from "react"
import { StatRibbon, type StatRibbonItem } from "@/components/composites/stats/StatRibbon"

/**
 * `PlaygroundDeviceSnapshot` — "Your machine": the paired agent's raw hardware
 * report turned into the same 4-cell `StatRibbon` the Lab route shows, so setup and
 * the live lab agree about what the machine can run. Reuses `StatRibbon`; the block
 * owns the domain judgement — bytes → GB rounding, the `win32`/`darwin`/`linux` →
 * "Windows"/"macOS"/"Linux" table, and the three sentences a GPU cell can say
 * depending on which of `gpu`/`vramTotalMb`/`vramFreeMb` came back. Every
 * `deviceInfo` combination and `isSkeleton` are states of the 4-cell shape.
 */

/**
 * The paired agent's hardware/OS snapshot, exactly as it arrives over the
 * `device:info` socket message — ported faithfully from
 * `PlaygroundDeviceInfo` in
 * `src/components/features/learn/Playground/PlaygroundPrepare/index.tsx`
 * (itself mirroring `PlaygroundByomDeviceInfoSocketIoMessage`).
 */
export interface PlaygroundDeviceInfo {
    /** `win32` | `linux` | `darwin`. */
    platform: string
    /** CPU architecture (`x64`, `arm64`, …). */
    arch: string
    /** Machine hostname. */
    hostname: string
    /** CPU model string. */
    cpuModel: string
    /** Logical CPU core count. */
    cpuCores: number
    /** Total RAM in bytes. */
    totalMemBytes: number
    /** Free RAM in bytes (at snapshot time). */
    freeMemBytes: number
    /** First discrete GPU name, or `null` if it couldn't be read. */
    gpu: string | null
    /** Free GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramFreeMb?: number
    /** Total GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramTotalMb?: number
}

/** Bytes → whole GB, the unit the ribbon reads in. */
const gbOf = (bytes: number): number => Math.round(bytes / 1e9)

/**
 * Node's `process.platform` id → the name a learner recognises.
 * @param platform - `win32` / `darwin` / `linux` (or anything else, passed through).
 */
const platformLabel = (platform: string): string =>
    platform === "win32"
        ? "Windows"
        : platform === "darwin"
            ? "macOS"
            : platform === "linux" ? "Linux" : platform

/**
 * The GPU cell's detail line: total + free VRAM when the agent could read an
 * NVIDIA card, an empty second line when a GPU exists but VRAM couldn't be
 * read, or an explicit "unknown" when no GPU was detected at all — three
 * distinct facts, not one string with a blank filled in.
 */
const vramDetail = (gpu: string | null, vramTotalMb?: number, vramFreeMb?: number): string =>
    vramTotalMb
        ? `${Math.round(vramTotalMb / 1024)} GB VRAM${vramFreeMb != null ? ` · ${vramFreeMb} MB free` : ""}`
        : gpu ? "" : "couldn't read"

/**
 * One ribbon cell's label: the fixed category word, plus the computed detail
 * when there is one — `StatRibbonItem.label` is a plain `string` (the ribbon
 * renders it itself through `Typography`), so caption and detail join into a
 * single line instead of the old two-line `<span>`.
 */
const deviceStatLabel = (caption: string, detail: string): string =>
    detail ? `${caption} · ${detail}` : caption

/** Props for {@link PlaygroundDeviceSnapshot}. */
export interface PlaygroundDeviceSnapshotProps {
    /** The paired machine's hardware/OS snapshot to render as a stat ribbon. */
    deviceInfo: PlaygroundDeviceInfo
    /** `true` → every cell's value/detail line swaps to its own shimmer. */
    isSkeleton?: boolean
}

/**
 * "Your machine": the paired agent's hardware report as a 4-cell stat ribbon
 * (OS · CPU · RAM · GPU). See the file header for the unit math, the
 * platform-name table, and why this composes `StatRibbon` instead of a new
 * shape.
 *
 * @param props - {@link PlaygroundDeviceSnapshotProps}
 */
const PlaygroundDeviceSnapshot = ({
    deviceInfo,
    isSkeleton = false,
}: PlaygroundDeviceSnapshotProps) => {
    const items: ReadonlyArray<StatRibbonItem> = [
        {
            key: "os",
            value: platformLabel(deviceInfo.platform),
            label: deviceStatLabel("Operating system", `${deviceInfo.arch} · ${deviceInfo.hostname}`),
        },
        {
            key: "cpu",
            value: `${deviceInfo.cpuCores} cores`,
            label: deviceStatLabel("CPU", deviceInfo.cpuModel),
        },
        {
            key: "ram",
            value: `${gbOf(deviceInfo.totalMemBytes)} GB`,
            label: deviceStatLabel("RAM", `${gbOf(deviceInfo.freeMemBytes)} GB free`),
        },
        {
            key: "gpu",
            value: deviceInfo.gpu ?? "—",
            label: deviceStatLabel("GPU", vramDetail(deviceInfo.gpu, deviceInfo.vramTotalMb, deviceInfo.vramFreeMb)),
        },
    ]

    return (
        <StatRibbon
            valueType="body"
            isSkeleton={isSkeleton}
            items={items}
        />
    )
}

export { PlaygroundDeviceSnapshot }

